JS = r'''
const form=document.querySelector('[data-search]');if(form){form.addEventListener('submit',e=>{e.preventDefault();const q=form.querySelector('[name=q]').value.trim(),city=form.querySelector('[name=city]').value;location.href='/zh/listings/?q='+encodeURIComponent(q)+'&city='+encodeURIComponent(city)})}const list=document.querySelector('[data-list]');if(list){const p=new URLSearchParams(location.search),q=(p.get('q')||'').toLowerCase(),city=(p.get('city')||'').toLowerCase();document.querySelectorAll('[data-filter-field]').forEach(x=>{if(p.has(x.name))x.value=p.get(x.name)});fetch('/data/listings.json').then(r=>r.json()).then(d=>{let xs=(d.items||[]).filter(x=>x.publish_status==='published');xs=xs.filter(x=>!q||JSON.stringify(x).toLowerCase().includes(q)).filter(x=>!city||JSON.stringify(x).toLowerCase().includes(city));const count=document.querySelector('[data-count]');if(count)count.textContent=xs.length+' 条已核验公开信息';if(!xs.length)return;list.innerHTML=xs.map(x=>`<article class="card"><span class="eyebrow">${esc(x.city_region||'越南')} · ${esc(x.category||'资产')}</span><h3>${esc(x.title_zh||x.title)}</h3><p>${esc(x.summary_zh||x.summary)}</p><p><a class="arrow" href="/listings/zh/${slug(x.id)}/">查看来源与详情 →</a></p></article>`).join('')}).catch(()=>{});}function esc(v){return String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function slug(v){return String(v||'item').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'item'}
'''

def shell(title: str, description: str, body: str, path: str, lang: str = "zh", schema: dict | None = None) -> str:
    locale, _ = LANGS[lang]
    canonical = f"{SITE}{path}"
    graph = schema or {"@context":"https://schema.org","@type":"WebPage","name":title,"url":canonical,"description":description,"inLanguage":locale}
    nav = {"zh": ("工业地产","城市","资产列表","合作机会","案例与信任","提交询盘"), "en": ("Industrial","Cities","Listings","Opportunities","Trust","Enquire"), "vi": ("BĐS công nghiệp","Khu vực","Danh sách","Hợp tác","Tin cậy","Liên hệ")}[lang]
    return f'''<!doctype html><html lang="{locale}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | VietnamZiChan</title><meta name="description" content="{html.escape(description, quote=True)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="zh-CN" href="{SITE}/zh/"><link rel="alternate" hreflang="vi-VN" href="{SITE}/vi/"><link rel="alternate" hreflang="en" href="{SITE}/en/"><meta property="og:title" content="{html.escape(title, quote=True)}"><meta property="og:description" content="{html.escape(description, quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:type" content="website"><meta name="twitter:card" content="summary"><link rel="stylesheet" href="/assets/site.css"><script type="application/ld+json">{json.dumps(graph,ensure_ascii=False).replace('</','<\\/')}</script></head><body><div class="top"><div class="wrap"><span>Vietnam property intelligence · Sources retained · Verify before transaction</span><span class="lang"><a href="/zh/">中文</a><a href="/vi/">Tiếng Việt</a><a href="/en/">English</a></span></div></div><div class="nav-shell"><nav class="wrap nav"><a class="brand" href="/{lang}/">VietnamZiChan<small>越南资产网 · Vietnam Assets</small></a><div class="links"><a href="/{lang}/categories/factory/">{nav[0]}</a><a href="/{lang}/cities/">{nav[1]}</a><a href="/{lang}/listings/">{nav[2]}</a><a href="/{lang}/opportunities/">{nav[3]}</a><a href="/{lang}/trust/">{nav[4]}</a></div><a class="action" href="/{lang}/contact/">{nav[5]}</a></nav></div>{body}<footer class="footer"><div class="wrap footer-grid"><div><h3>VietnamZiChan</h3><p>越南工业地产、商业资产与跨境合作的公开信息发现入口。保留来源，关键条件再次核验。</p></div><div><h3>资产</h3><a href="/{lang}/categories/factory/">厂房</a><a href="/{lang}/categories/industrial-land/">工业土地</a><a href="/{lang}/categories/warehouse/">仓库物流</a></div><div><h3>服务</h3><a href="/{lang}/listings/">搜索筛选</a><a href="/{lang}/contact/">发布与询盘</a><a href="/{lang}/trust/">核验原则</a></div></div><div class="wrap fine">公开信息不构成交易、投资或法律建议。价格、产权、可用状态与合作条件须向原始发布方及专业顾问复核。</div></footer><script src="/assets/site.js" defer></script></body></html>'''

def cards(items, base, lang="zh"):
    idx={"zh":0,"en":1,"vi":2}[lang]
    return '<div class="grid">'+''.join(f'<a class="card" href="/{lang}/{base}/{slug}/"><span class="eyebrow">Vietnam market</span><h3>{html.escape(v[idx])}</h3><p>{html.escape(v[3])}</p><span class="arrow">查看专题 →</span></a>' for slug,v in items.items())+'</div>'

def home(lang="zh"):
    copy={"zh":("越南资产，从发现到核验","搜索越南厂房、工业土地、仓库、酒店与跨境合作机会。按城市与资产类型组织公开信息，保留来源并提供统一询盘入口。","搜索厂房、土地、仓库或合作需求"),"en":("Vietnam assets, from discovery to verification","Explore factories, industrial land, warehouses, hotels and cross-border opportunities. Source-led discovery with a clear verification path.","Search assets or opportunities"),"vi":("Tài sản Việt Nam, từ tìm kiếm đến xác minh","Khám phá nhà xưởng, đất công nghiệp, kho vận, khách sạn và cơ hội hợp tác với nguồn thông tin minh bạch.","Tìm tài sản hoặc cơ hội")}[lang]
    body=f'''<header class="hero"><div class="wrap hero-grid"><div><span class="kicker">Industrial property · Commercial assets · Cooperation</span><h1>{copy[0]}</h1><p>{copy[1]}</p><form class="search" data-search><input name="q" aria-label="关键词" placeholder="{copy[2]}"><select name="city" aria-label="城市"><option value="">全部重点城市</option>{''.join(f'<option value="{v[0]}">{v[0]}</option>' for v in CITIES.values())}</select><button class="btn">搜索</button></form></div><aside class="proof"><div><b>6 类</b>核心资产入口</div><div><b>7 地</b>重点产业城市</div><div><b>100%</b>来源与核验状态保留</div></aside></div></header><main><section class="section"><div class="wrap"><div class="head"><div><h2>按资产类型进入</h2><p>围绕真实业务问题组织，不做杂乱信息堆积。</p></div><a class="arrow" href="/{lang}/listings/">查看全部 →</a></div>{cards(CATEGORIES,'categories',lang)}</div></section><section class="section industrial"><div class="wrap"><div class="head"><div><h2>工业地产重点</h2><p>制造业选址、现成厂房、工业土地和仓储物流。</p></div></div>{cards(dict(list(CATEGORIES.items())[:3]),'categories',lang)}</div></section><section class="section"><div class="wrap"><div class="head"><div><h2>重点城市与产业走廊</h2><p>用城市专题承接区域比较、选址知识与最新公开信息。</p></div></div>{cards(CITIES,'cities',lang)}</div></section><section class="section"><div class="wrap"><div class="cta"><div><h2>告诉我们你在越南要找什么</h2><p>提交城市、面积、预算、用途和时间表。AI 匹配入口已预留，目前由规则筛选与人工核验承接。</p></div><a class="btn" href="/{lang}/contact/">提交需求</a></div></div></section></main>'''
    schema={"@context":"https://schema.org","@graph":[{"@type":"Organization","name":"VietnamZiChan","url":SITE},{"@type":"WebSite","name":"VietnamZiChan","url":f"{SITE}/{lang}/","potentialAction":{"@type":"SearchAction","target":f"{SITE}/{lang}/listings/?q={{search_term_string}}","query-input":"required name=search_term_string"}}]}
    return shell(copy[0],copy[1],f"{body}",f"/{lang}/",lang,schema)

def landing(kind, slug, data, lang="zh"):
    idx={"zh":0,"en":1,"vi":2}[lang]; name=data[idx]; desc=data[3]
    noun="资产类型" if kind=="categories" else "重点城市"
    faq=f'''<section class="section faq"><div class="wrap"><div class="head"><div><h2>常见问题</h2><p>给搜索引擎和决策者都能直接理解的答案。</p></div></div><details><summary>{name}的信息是否已核验？</summary><p>页面只展示通过发布门槛的公开信息，并保留来源与核验状态；价格、产权和即时可用性仍需二次确认。</p></details><details><summary>如何提交具体需求？</summary><p>在询盘页填写城市、用途、面积、预算和时间表。系统会先按结构化条件筛选，再进入人工核验。</p></details></div></section>'''
    body=f'''<main><div class="page-hero"><div class="wrap"><div class="breadcrumb"><a href="/{lang}/">首页</a> / {noun}</div><span class="kicker">Vietnam market guide</span><h1>{name}</h1><p>{desc}。本专题汇总相关公开资产、选址问题、核验要点和询盘入口。</p><div class="facts"><div class="fact"><b>先定义需求</b><br><span>用途、面积、预算、时间</span></div><div class="fact"><b>再核验来源</b><br><span>状态、产权、限制条件</span></div><div class="fact"><b>最后对接</b><br><span>现场、顾问与交易文件</span></div></div></div></div><section class="section"><div class="wrap listing-layout"><aside class="filters"><span class="eyebrow">筛选建议</span><h3>把需求说清楚</h3><p>城市 / 园区<br>租赁 / 购买<br>建筑面积 / 土地面积<br>电力 / 层高 / 消防<br>交付时间</p><a class="btn" href="/{lang}/contact/">提交结构化需求</a></aside><div><div class="head"><div><h2>{name}公开信息</h2><p data-count>读取已发布数据…</p></div></div><div class="grid" data-list><div class="empty full"><h3>当前没有通过发布门槛的信息</h3><p>我们不以演示房源冒充真实资产。可先提交需求，或稍后查看经来源核验的新条目。</p><a class="arrow" href="/{lang}/contact/">登记需求 →</a></div></div></div></div></section>{faq}</main>'''
    schema={"@context":"https://schema.org","@graph":[{"@type":"CollectionPage","name":name,"description":desc,"url":f"{SITE}/{lang}/{kind}/{slug}/"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":f"{name}的信息是否已核验？","acceptedAnswer":{"@type":"Answer","text":"仅展示通过发布门槛并保留来源的信息；关键交易条件仍需二次确认。"}}]}]}
    return shell(f"{name}｜越南{noun}",desc,body,f"/{lang}/{kind}/{slug}/",lang,schema)

def simple_page(name,path,content,lang="zh"):
    body=f'<main><div class="page-hero"><div class="wrap"><div class="breadcrumb"><a href="/{lang}/">首页</a> / {name}</div><h1>{name}</h1><p>{content}</p></div></div><section class="section"><div class="wrap">'
    if path=="listings": body+='''<div class="listing-layout"><aside class="filters"><form data-search><label>关键词</label><input name="q" placeholder="城市、类型、用途"><label>城市</label><select name="city"><option value="">全部城市</option>'''+''.join(f'<option>{v[0]}</option>' for v in CITIES.values())+'''</select><p><button class="btn">筛选</button></p></form></aside><div><div class="head"><div><h2>公开资产与合作信息</h2><p data-count>读取中…</p></div></div><div class="grid" data-list><div class="empty full"><h3>暂无通过发布门槛的信息</h3><p>数据工厂正在持续清洗、去重和核验。不会使用虚构条目填充页面。</p></div></div></div></div>'''
    elif path=="contact": body+='''<form class="form" name="inquiry" method="POST" data-netlify="true" netlify-honeypot="bot-field"><input type="hidden" name="form-name" value="inquiry"><p hidden><label>不要填写 <input name="bot-field"></label></p><div class="form-grid"><label>您的姓名<input name="name" required></label><label>公司 / 机构<input name="company"></label><label>联系方式<input name="contact" required placeholder="邮箱、电话或微信"></label><label>需求类型<select name="type"><option>寻找厂房</option><option>寻找工业土地</option><option>寻找仓库</option><option>出售/出租资产</option><option>跨境合作</option><option>其他</option></select></label><label>目标城市<input name="city"></label><label>预算 / 面积<input name="budget_area"></label><label class="full">需求详情<textarea name="message" required placeholder="用途、时间表、关键条件"></textarea></label><label class="full"><input style="width:auto" type="checkbox" required> 我理解平台信息需进一步核验</label><div class="full"><button class="btn" type="submit">提交询盘</button></div></div></form>'''
    elif path=="trust": body+='''<div class="grid"><div class="card step"><h3>来源保留</h3><p>原始链接、发布时间、采集时间和内容指纹进入内容合同。</p></div><div class="card step"><h3>自动清洗</h3><p>规则完成字段校验、追踪参数清理、重复检测和风险标记。</p></div><div class="card step"><h3>发布门槛</h3><p>只有 published 状态进入公开列表；hidden 不会展示。</p></div><div class="card step"><h3>交易前复核</h3><p>价格、产权、可用状态、许可与合同必须由项目方及专业顾问确认。</p></div><div class="card"><h3>案例说明</h3><p>当前不展示未经授权的客户名称或虚构成交案例。后续仅发布可验证、获授权的案例。</p></div><div class="card"><h3>AI 使用边界</h3><p>AI 仅用于整理、分类和匹配建议，不替代法律、财务或现场尽调。</p></div></div>'''
    else: body+='''<div class="grid"><div class="card"><h3>中国企业进入越南</h3><p>厂房、园区、仓储、设备、供应链与本地合作资源。</p></div><div class="card"><h3>越南项目对接中国资源</h3><p>设备、货源、渠道、技术、采购及联合经营。</p></div><div class="card"><h3>合作发布原则</h3><p>说明主体、目标、资源、时间表和可验证联系方式。</p></div></div><div class="notice" style="margin-top:20px">合作机会不等于投资建议或信用背书。平台会保留来源并标注核验状态。</div>'''
    body+='</div></section></main>'
    return shell(name,content,body,f"/{lang}/{path}/",lang)

def write(path, text):
    target=ROOT/path; target.parent.mkdir(parents=True,exist_ok=True); target.write_text(text+"\n",encoding="utf-8")

def build():
    write("assets/site.css",CSS); write("assets/site.js",JS)
    write(".portal-built.json", json.dumps({"schema_version":"1.0","runtime":"static-local"}, ensure_ascii=False))
    write("index.html",'<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=/zh/"><link rel="canonical" href="https://vietnamzichan.com/zh/"><title>VietnamZiChan</title></head><body><a href="/zh/">进入越南资产网</a></body></html>')
    urls=["/"]
    for lang in LANGS:
        write(f"{lang}/index.html",home(lang)); urls.append(f"/{lang}/")
        write(f"{lang}/cities/index.html",shell("越南重点城市","越南重点工业与商业城市导航",f'<main><div class="page-hero"><div class="wrap"><h1>越南重点城市</h1><p>按产业集群、物流条件和资产类型进入区域专题。</p></div></div><section class="section"><div class="wrap">{cards(CITIES,"cities",lang)}</div></section></main>',f"/{lang}/cities/",lang)); urls.append(f"/{lang}/cities/")
        for kind, dataset in (("categories",CATEGORIES),("cities",CITIES)):
            for slug,data in dataset.items(): write(f"{lang}/{kind}/{slug}/index.html",landing(kind,slug,data,lang)); urls.append(f"/{lang}/{kind}/{slug}/")
        for slug,name,desc in (("listings","资产搜索与筛选","搜索已通过发布门槛的越南资产与合作信息。"),("contact","发布资产 / 提交询盘","结构化提交资产、选址或跨境合作需求。"),("trust","案例与信任","了解信息来源、核验门槛、AI 使用边界与案例发布原则。"),("opportunities","跨境合作机会","连接中国企业与越南本地资产、供应链及合作资源。")):
            write(f"{lang}/{slug}/index.html",simple_page(name,slug,desc,lang)); urls.append(f"/{lang}/{slug}/")
    sitemap='<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'<url><loc>{SITE}{u}</loc></url>\n' for u in urls)+'</urlset>'
    write("sitemap.xml",sitemap); write("robots.txt",f"User-agent: *\nAllow: /\nSitemap: {SITE}/sitemap.xml")
    return len(urls)

if __name__ == "__main__": print(json.dumps({"status":"ok","pages":build()},ensure_ascii=False))
